<span class="line">    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">final</span> <span class="token class-name">String</span> <span class="token constant">ZK_BASE_PATH</span> <span class="token operator">=</span> <span class="token string">&quot;/binghe_rpc&quot;</span><span class="token punctuation">;</span></span>
